    표8_상담적용: [
        {"상황":"자신의 능력이나 언변을 자랑하며 교만해진 분", "성경원리":"고린도 성도들의 구변과 지식은 하나님이 그리스도 안에서 주신 것이다. 자랑할 근거가 없다", "실제적용":"내가 가진 능력의 근원을 추적해보라. 결국 하나님의 은혜다. 그 깨달음이 겸손의 기초가 된다"},
        {"상황":"자신에게 특별한 은사가 없다고 느끼는 분", "성경원리":"'모든 구변과 지식'이 주어졌다는 것은 은사의 다양함을 의미한다. 모든 성도에게 은사가 있다", "실제적용":"아직 발견하지 못한 것일 수 있다. 기도하며 자신이 무엇을 할 때 기쁨이 있는지 어떤 일에 열매가 있는지 살펴보라"},
        {"상황":"지식은 많은데 삶에 변화가 없는 분", "성경원리":"지식(그노시스)은 그리스도 안에서 받아야 참되다. 그리스도와의 관계 없는 지식은 교만만 키운다 (고전 8:1)", "실제적용":"지식이 기도와 순종으로 연결되는지 점검하라. 아는 것이 삶으로 나오지 않는다면 그 지식이 어디서 왔는지 돌아보라"}
    ],
