        {"상황":"신앙의 지적 의심이 많은 청년 성도", "성경원리":"하나님은 이성을 초월하시지만 이성에 반하지 않으신다. 믿음과 이성은 함께 갈 수 있다", "실제적용":"지적 질문을 존중하며 함께 성경을 탐구하되, 이성만으로는 신앙에 도달할 수 없음을 부드럽게 나눈다"},
        {"상황":"신앙이 자신의 기대대로 이루어지지 않아 실망한 성도", "성경원리":"하나님은 우리의 기대를 충족시키는 분이 아니라 우리를 변화시켜 그분의 형상을 닮게 하시는 분이다", "실제적용":"하나님의 목적이 우리의 안락이 아닌 성화와 영화임을 나누고, 현재의 고난 속에서 하나님의 더 큰 목적을 볼 수 있도록 돕는다"}
