        {"새찬송가":"304", "통일찬송가":"404", "제목":"그 크신 하나님의 사랑", "선정이유":"하나님의 크신 능력과 택하심을 찬양"},
        {"새찬송가":"14", "통일찬송가":"14", "제목":"온 천하 만물 우러러", "선정이유":"하나님의 주권과 능력을 찬양하는 찬송"},
        {"새찬송가":"406", "통일찬송가":"463", "제목":"내 주는 강한 성이요", "선정이유":"약한 자에게 강하신 하나님이 보호이심을 노래"}
