        {"원어":"καταργήσῃ (카타르게세)", "의미_문법":"폐하려 - 부정과거 가정법, '완전히 무효화하다, 기능을 정지시키다'", "설교포인트":"하나님은 세상의 있는 것들을 없는 것들로 무효화하신다"}
