        {"교리":"은혜의 절대성", "설명":"자랑이 제거된다는 것은 구원이 순전한 은혜임을 의미한다. 인간의 어떤 기여도 없는 완전한 은혜만이 하나님 앞에서의 자랑을 제거한다", "관련구절":"롬 11:6, 딛 3:5, 갈 2:16"},
        {"교리":"하나님의 영광의 독점성", "설명":"구원에서 하나님만이 영광을 받으신다. 피조물인 인간이 창조자 하나님 앞에서 자랑하는 것은 존재 질서의 전도이다", "관련구절":"사 42:8, 사 48:11, 롬 11:36"}
