        {"원어":"δικαιοσύνη (디카이오쉬네)", "의미_문법":"의로움 - 하나님 앞에서의 올바른 관계, 칭의", "설교포인트":"그리스도가 우리의 의가 되셨으므로 우리는 그분 안에서 의롭다"},
        {"원어":"ἀπολύτρωσις (아폴뤼트로시스)", "의미_문법":"구속함 - 값을 치르고 해방시키는 것, 죄의 속박에서의 해방", "설교포인트":"그리스도가 몸소 값을 치르고 우리를 죄에서 해방하셨다"}
