        {"상황":"항상 강해 보여야 한다는 압박으로 지친 교회 지도자", "성경원리":"인간적 강함이 아닌 하나님의 능력이 사역의 원천이므로, 자신의 연약함을 인정하는 것이 더 강한 사역을 가능하게 한다", "실제적용":"공동체 안에서 서로의 약함을 나눌 수 있는 안전한 공간을 만들고, 상호 기도와 지지를 실천한다"}
