        {"구절":"계 21:1-4", "연결점":"새 하늘과 새 땅이 나타날 것이며 하나님이 모든 눈물을 닦아주실 것이다", "구분":"신약"},
        {"구절":"엡 3:20", "연결점":"우리가 구하거나 생각하는 모든 것보다 더 넘치도록 하실 수 있는 분", "구분":"신약"}
