        {"항목":"상호 책임의 원리", "내용":"세상이 성령 받은 자를 평가할 수 없다는 것은 성도가 어떤 책임도 없다는 것이 아니다. 성도들은 서로에게, 그리고 하나님께 책임이 있다 (고전 4:3-5)", "목회적활용":"자유와 책임의 균형을 가르친다"}
