        {"구분":"다니엘의 분별", "내용":"다니엘은 바벨론 문화에서 영적 분별로 모든 것을 바르게 판단했다 (단 1장, 5장)", "그리스도연결":"성령 받은 자는 어떤 문화와 상황에서도 영적으로 분별하는 능력을 가진다"},
        {"구분":"엘리야의 영적 통찰", "내용":"엘리야는 7,000명이 바알에게 무릎 꿇지 않았음을 알지 못했으나 하나님이 알려주셨다 (왕상 19:18). 성령의 계시가 분별의 근거이다", "그리스도연결":"성령이 하나님의 것을 우리에게 알리시어 영적 분별을 가능하게 하신다"}
