        {"새찬송가":"24", "통일찬송가":"24", "제목":"기뻐하며 경배하세", "선정이유":"모든 것의 주인이신 하나님을 경배"},
        {"새찬송가":"40", "통일찬송가":"40", "제목":"찬양하라 내 영혼아", "선정이유":"하나님의 주권과 위대하심을 찬양"},
        {"새찬송가":"588", "통일찬송가":"390", "제목":"주님의 뜻을 이루소서", "선정이유":"도구로서 하나님의 뜻에 순종"}
