        {"상황":"자신의 능력으로 모든 것을 해결하려는 성도", "성경원리":"자라게 하시는 분은 하나님이시다. 인간의 능력과 노력의 한계를 인정하고 하나님을 의지해야 한다", "실제적용":"자신의 능력의 한계를 인정하고, 기도와 하나님 의존을 실천하도록 돕라"},
        {"상황":"자신의 무능함으로 좌절하는 성도", "성경원리":"심는 자와 물 주는 자는 아무것도 아니지만 그 역할을 하나님이 귀히 사용하신다. 자신의 작음이 하나님의 역사를 막지 않는다", "실제적용":"자신의 한계를 인정하면서도 하나님이 그 약한 것을 통해 일하심을 믿도록 격려하라"},
        {"상황":"사역의 열매를 자신의 공으로 여기는 경향이 있는 사역자", "성경원리":"자라게 하시는 분은 하나님이시다. 사역의 열매는 하나님이 주신 것이다", "실제적용":"사역의 열매를 볼 때마다 하나님께 감사하는 훈련을 하고, 성도들에게도 하나님의 은혜로 돌리도록 가르치라"}
