        {"구절":"시 118:22", "연결점":"건축자가 버린 돌이 집 모퉁이의 머릿돌이 되었나니", "구분":"구약"},
        {"구절":"요 14:6", "연결점":"나는 길이요 진리요 생명이니 나로 말미암지 않고는 아버지께로 올 자가 없느니라", "구분":"신약"}
