    표2_역사적배경: [
        {"항목":"건축 재료의 상징", "내용":"당시 지중해 세계에서 중요한 건축물은 돌과 금속으로, 평범한 건물은 나무와 짚으로 지어졌다. 귀족의 저택과 평민의 집이 재료로 구분되었다", "목회적활용":"사역의 질과 내용에 있어 가장 귀한 것을 추구하라"},
        {"항목":"구약 성전의 재료들", "내용":"솔로몬 성전에는 금, 은, 보석, 백향목 등 가장 귀한 재료들이 사용되었다 (왕상 6-7장). 바울이 이 비유를 통해 성전과 교회를 연결한다", "목회적활용":"하나님의 집을 세우는 데 최선의 것을 드려야 한다"},
        {"항목":"심판의 불 개념", "내용":"13절의 '불로 시험함'은 연단의 불로서, 구약의 예언적 심판 이미지와 연결된다 (말 3:2-3, 슥 13:9). 불은 귀한 것을 정제하고 값없는 것을 태운다", "목회적활용":"심판의 날에 영원한 것만이 남을 것임을 가르치라"}
    ],
    표3_신학적의미: [
        {"교리":"심판론", "설명":"모든 사역은 심판의 날에 검증된다. 기초 위에 무엇을 세웠느냐가 평가의 대상이다. 사역의 질이 중요하다", "관련구절":"고후 5:10, 고전 4:5, 롬 14:10"},
        {"교리":"사역론", "설명":"기초 위에 세우는 사역자들은 다양하고, 그 사역의 질도 다양하다. 좋은 재료로 세우는 것이 사역자의 책임이다", "관련구절":"딤후 4:2, 골 1:28, 엡 4:12"},
        {"교리":"교훈론", "설명":"교회를 세우는 교훈과 가르침의 질이 중요하다. 순수한 복음과 말씀에 근거한 가르침이 금은보석이요, 인간적 지혜와 세상 철학은 나무풀짚이다", "관련구절":"딤후 2:15, 딛 2:1, 골 2:8"}
    ],
    표4_예표론: [
        {"구분":"솔로몬 성전의 재료들", "내용":"가장 귀한 재료들로 건축된 솔로몬 성전. 하나님께 드리는 최선의 표현이었다", "그리스도연결":"교회도 최선의 가르침과 섬김으로 세워져야 한다"},
        {"구분":"말라기의 정련의 불", "내용":"여호와의 날이 정련의 불처럼 올 것이라 (말 3:2-3). 레위 자손을 정금같이 단련하신다", "그리스도연결":"심판의 날에 모든 사역이 불로 시험받을 것이다"},
        {"구분":"다니엘의 금 신상", "내용":"금 머리에서 철과 흙의 발까지 다양한 재료의 신상. 각 재료가 다른 왕국을 상징했다 (단 2장)", "그리스도연결":"세상의 재료들이 모두 무너지지만 하나님의 나라 반석은 영원하다"}
    ],
    표5_매튜헨리: [
        {"영어원문":"By gold, silver, precious stones, he means solid, valuable, lasting doctrines and duties. By wood, hay, stubble, he means slight, worthless, or erroneous matter built on the right foundation.", "한국어번역":"금, 은, 보석으로 그는 견고하고 가치 있고 지속적인 교리와 의무들을 의미한다. 나무, 풀, 짚으로 그는 올바른 기초 위에 세워진 가볍고 쓸모없거나 잘못된 내용을 의미한다.", "핵심통찰":"사역의 질이 재료의 귀함으로 비유된다"},
        {"영어원문":"Men may build on the right foundation and yet build badly. They may hold the truth of the gospel and yet add many errors, weaknesses, and corruptions.", "한국어번역":"사람들이 올바른 기초 위에 세울 수 있지만 그래도 잘못 세울 수 있다. 그들이 복음의 진리를 붙들면서도 많은 오류, 약점, 부패를 더할 수 있다.", "핵심통찰":"올바른 기초 위에서도 잘못 세울 수 있다"},
        {"영어원문":"The question is not whether you build on the right foundation, but how you build — what materials you use, what doctrines and practices you employ.", "한국어번역":"문제는 올바른 기초 위에 세우느냐가 아니라 어떻게 세우느냐이다 — 어떤 재료를, 어떤 교리와 실천을 사용하느냐이다.", "핵심통찰":"기초가 맞아도 세우는 방법과 재료가 중요하다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"무엇으로 세우는가 - 사역 재료의 중요성", "예화_적용":"같은 자리에 지은 집도 재료에 따라 수명이 천양지차이다"},
        {"대지":"서론", "내용":"기초는 예수 그리스도이다. 이것은 확정되었다. 그렇다면 그 위에 무엇으로 세우느냐가 다음 과제이다. 바울은 여섯 가지 재료를 나열하며 그 차이를 가르친다", "예화_적용":"집의 부지는 같아도 어떤 재료로 짓느냐에 따라 20년 후 모습이 완전히 다르다"},
        {"대지":"1대지: 귀한 재료 - 금, 은, 보석", "내용":"순수한 복음의 진리, 하나님의 말씀에 근거한 가르침, 그리스도 중심의 삶의 실천이 귀한 재료이다", "예화_적용":"좋은 재료로 지은 집은 시간이 지나도 가치를 유지하며 오히려 더 빛난다"},
        {"대지":"2대지: 값싼 재료 - 나무, 풀, 짚", "내용":"인간의 지혜, 세상의 철학, 청중의 귀를 즐겁게 하는 가르침, 외형만 있는 종교 행위가 값싼 재료이다", "예화_적용":"짚으로 지은 집은 한여름 더위나 한겨울 추위를 막지 못한다"},
        {"대지":"3대지: 재료의 차이는 시험으로 드러난다", "내용":"재료의 차이는 당장 눈에 보이지 않을 수 있다. 그러나 불로 시험받는 날에 모든 것이 드러난다", "예화_적용":"새 건물일 때는 재료 차이를 모른다. 재난이 올 때 비로소 차이가 드러난다"},
        {"대지":"결론", "내용":"나는 어떤 재료로 신앙의 집을 세우고 있는가? 말씀에 근거한 귀한 재료로 세우고 있는가, 아니면 세상적이고 인간적인 재료로 쌓고 있는가? 오늘부터 귀한 재료를 선택하자", "예화_적용":"집을 지을 때 비용을 아끼려 저급한 재료를 쓰면 나중에 더 큰 비용이 든다"}
    ],
