        {"새찬송가":"216", "통일찬송가":"210", "제목":"달고 오묘한 그 말씀", "선정이유":"말씀을 귀히 여기는 신앙"},
        {"새찬송가":"455", "통일찬송가":"389", "제목":"내 너를 위하여", "선정이유":"하나님을 위해 귀한 것을 드리는 헌신"},
        {"새찬송가":"323", "통일찬송가":"338", "제목":"부름 받아 나선 이 몸", "선정이유":"귀한 사역을 향한 헌신"}
