    표5_매튜헨리: [
        {"영어원문":"He shall be saved, yet so as by fire — he escapes, but with the loss of his work. He shall save his soul, though with difficulty, like a brand plucked from the burning.", "한국어번역":"그는 구원을 얻을 것이나 불 가운데서와 같이 — 그는 탈출하지만 자신의 사역을 잃고. 그는 자기 영혼을 구원하되, 불에서 빼낸 타다 남은 가지처럼 어렵게.", "핵심통찰":"구원은 확실하지만 사역 손실의 비극도 실재한다"},
        {"영어원문":"This is no encouragement to careless building; it is a warning. Better to build with gold and silver and precious stones and receive a reward, than with wood and hay and stubble and suffer loss.", "한국어번역":"이것은 부주의한 건축을 장려하는 것이 아니다. 경고이다. 나무와 풀과 짚으로 세워 손실을 입는 것보다 금과 은과 보석으로 세워 상을 받는 것이 낫다.", "핵심통찰":"빈 손으로 구원받는 것은 경고이지 위안이 아니다"},
        {"영어원문":"A minister who has built with bad materials may be saved himself, though he has been a means of perverting and ruining others.", "한국어번역":"잘못된 재료로 세운 사역자는 자신은 구원받을 수 있으나, 다른 이들을 왜곡시키고 망하게 하는 수단이 되어 있을 수 있다.", "핵심통찰":"잘못된 사역은 자신뿐 아니라 다른 이들에게도 해를 끼친다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"불 가운데서 얻은 구원 - 경고이며 소망", "예화_적용":"집이 불타도 사람은 살아 나오는 경우가 있다. 이것은 기쁜 일이지만 동시에 모든 것을 잃은 비극이다"},
        {"대지":"서론", "내용":"사역이 불타도 구원을 잃지 않는다는 이 말씀은 위안인가 경고인가? 둘 다이다. 구원의 확실성은 위안이고, 빈손으로 겨우 탈출하는 이미지는 분명한 경고이다", "예화_적용":"화재 현장에서 살아 나온 것은 감사하지만 모든 것을 잃은 것은 비극이다"},
        {"대지":"1대지: 구원은 은혜로 확실하다", "내용":"사역이 불타도 구원을 잃지 않는다. 구원은 사역의 결과가 아닌 은혜이다. 이것은 진정한 위안이다", "예화_적용":"여권이 있으면 빈 손으로 귀국해도 본국에 들어올 수 있다. 그리스도의 구원은 확실한 여권이다"},
        {"대지":"2대지: 그러나 손실은 실재한다", "내용":"빈손으로 구원받는 것은 비극이다. 사역의 손실은 실제로 있다. 이것은 무가치한 사역에 대한 분명한 경고이다", "예화_적용":"평생 모은 재산을 화재로 잃고 노후를 맞이하는 슬픔을 생각해 보라"},
        {"대지":"3대지: 지금 선택이 중요하다", "내용":"지금 어떤 재료로 세우느냐가 그 날에 무엇이 남느냐를 결정한다. 귀한 재료로 충성되게 세우자", "예화_적용":"지금 저축하지 않으면 나중에 후회한다. 지금 귀한 사역으로 쌓지 않으면 나중에 아무것도 없다"},
        {"대지":"결론", "내용":"구원은 확실하다. 그러나 빈손으로 구원받는 것은 비극이다. 오늘부터 귀한 재료로, 충성된 마음으로 사역을 세워가자. 그 날에 상급과 함께 구원을 얻자", "예화_적용":"은행 계좌가 비어 있어도 살 수 있다. 그러나 풍요롭게 사는 것과 빈곤하게 사는 것은 다르다"}
    ],
