        {"새찬송가":"310", "통일찬송가":"190", "제목":"아 하나님의 은혜로", "선정이유":"은혜로 구원받음을 찬양"},
        {"새찬송가":"455", "통일찬송가":"389", "제목":"내 너를 위하여", "선정이유":"구원의 감사로 충성된 사역을 드림"},
        {"새찬송가":"408", "통일찬송가":"392", "제목":"믿음으로 서리라", "선정이유":"은혜의 구원 위에 굳게 서는 신앙"}
