        {"상황":"평생 사역했는데 아무 열매가 없다고 느끼는 목회자", "성경원리":"사역의 열매가 없어 보여도 구원은 확실하다. 그러나 하나님 앞에서 충성된 사역을 돌아볼 필요가 있다", "실제적용":"하나님 앞에서 자신의 사역을 점검하고, 귀한 재료로 세운 부분이 무엇인지 함께 찾도록 도우라"}
