    표5_매튜헨리: [
        {"영어원문":"God knows the thoughts of men to be vain — not worth knowing, not likely to lead to any good end, not answering the purposes for which they are devised.", "한국어번역":"하나님은 사람들의 생각이 헛된 것임을 아신다 — 알 가치가 없고, 어떤 좋은 목적으로 이어지지 않으며, 그것들이 계획된 목적에 부응하지 못한다.", "핵심통찰":"인간의 생각이 하나님의 목적을 이루지 못한다"},
        {"영어원문":"How foolish then is the man who rests in his own thoughts, and does not submit them to the Divine wisdom and guidance!", "한국어번역":"그렇다면 자신의 생각에 안주하며 그것들을 신적 지혜와 인도에 복종시키지 않는 사람은 얼마나 어리석은가!", "핵심통찰":"자신의 생각에 안주하는 것이 어리석음이다"},
        {"영어원문":"We should therefore take heed of self-sufficiency in our reasonings, and diligently seek the wisdom that comes from above.", "한국어번역":"그러므로 우리는 우리의 추론에서 자기 충족을 조심해야 하고, 위에서 오는 지혜를 부지런히 구해야 한다.", "핵심통찰":"인간적 추론의 자기 충족을 경계하고 하나님의 지혜를 구하라"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"하나님이 아신다 - 지혜로운 자들의 생각이 헛됨", "예화_적용":"아이의 숨겨진 계획을 부모는 안다. 하나님은 인간의 모든 생각을 아신다"},
        {"대지":"서론", "내용":"인간이 아무리 정교한 생각과 계획을 세워도 하나님이 아신다. 그리고 그것이 헛된 것임을 아신다. 이 진리는 겸손을 촉구한다", "예화_적용":"상사는 직원들의 모든 행동과 계획을 파악하고 있다. 하나님은 우리의 모든 생각을 완전히 아신다"},
        {"대지":"1대지: 하나님은 완전히 아신다", "내용":"감추는 생각도, 정교한 계획도 하나님 앞에 완전히 드러나 있다. 전지하신 하나님 앞에 숨겨진 것은 없다", "예화_적용":"투명한 유리로 된 집에서는 아무것도 숨길 수 없다. 하나님 앞에서의 삶도 완전히 투명하다"},
        {"대지":"2대지: 지혜로운 자들의 생각이 헛됨", "내용":"세상에서 가장 지혜로운 자의 생각도 하나님의 목적과 다를 때 헛된 것이다. 인간 지혜의 근본적 한계이다", "예화_적용":"고도로 발달한 AI도 창조주 하나님의 지혜에는 미치지 못한다"},
        {"대지":"3대지: 하나님의 지혜로 생각하라", "내용":"헛된 생각을 버리고 하나님의 지혜로 생각하는 것이 지혜이다. 말씀과 기도로 생각의 방향을 바꾸라", "예화_적용":"잘못된 나침반을 올바른 나침반으로 교체해야 한다"},
        {"대지":"결론", "내용":"내 생각은 하나님의 뜻과 일치하는가? 헛된 생각에 시간을 낭비하지 말고 하나님의 지혜로 생각하는 자가 되자", "예화_적용":"좋은 종자를 심어야 좋은 열매를 맺는다. 하나님의 지혜로 생각해야 좋은 삶의 열매를 맺는다"}
    ],
