        {"원어":"Χριστὸς δὲ θεοῦ (크리스토스 데 데우)", "의미_문법":"그리스도는 하나님의 것 - 주격+속격. 삼위일체의 관계", "설교포인트":"그리스도도 하나님 아버지께 속해 있다. 종속이 아닌 사랑의 관계이다"}
