        {"상황":"고난으로 인해 신앙이 흔들리는 성도", "성경원리":"현재의 고난이 그리스도인의 정상적인 상태이다. 바울도 사도로서 고난받았다", "실제적용":"고난을 이상한 것으로 보지 않도록 돕고, 고난이 영광 전의 과정임을 이해하게 하여 소망을 갖도록 격려하라"}
