        {"항목":"고린도 교인들의 자기 만족", "내용":"8절의 '왕 노릇'과 극명한 대조. 고린도 교인들은 영적 성공을 누리는 반면 사도들은 죽음의 구경거리", "목회적활용":"물질적 풍요와 영적 교만이 복음 현실 인식을 왜곡시킨다"}
