        {"항목":"그리스 명예-수치 문화", "내용":"고대 그리스 로마 사회는 공적 명예(τιμή)를 최고 가치로 여김. ἔνδοξοι(존귀)와 ἄδοξοι(비천)의 대조는 사회적 계층을 반영", "목회적활용":"복음은 명예-수치 체계를 전복시킨다. 비천한 자가 그리스도 안에서 존귀함"},
        {"항목":"바울의 반어법(irony)", "내용":"이 구절은 강한 반어법. 사도들의 어리석음과 비천함이 오히려 진정한 복음의 표지임을 역설", "목회적활용":"세상의 성공과 인정을 복음 사역의 척도로 삼는 태도를 비판"}
