        {"항목":"후욕에 축복하기", "내용":"λοιδορούμενοι εὐλογοῦμεν은 예수님의 산상수훈(마 5:44)과 롬 12:14의 실천. 당시 사회에서 혁명적 행동", "목회적활용":"복음은 세상의 보복 문화를 전복하는 새로운 사회 윤리를 만든다"},
        {"항목":"1세기 노동의 사회적 의미", "내용":"그리스-로마 귀족 문화에서 손 노동은 천한 것으로 여겨짐. 바울의 노동은 사회적 굴욕이었으나 그는 이를 자랑함", "목회적활용":"복음은 노동의 존엄성을 회복시킨다"}
