        {"교리":"악에 선으로 갚기", "설명":"후욕에 축복 — 원수 사랑의 실천(마 5:44). 그리스도께서 십자가에서 저들을 사하여 달라고 기도하신 모범을 따름", "관련구절":"롬 12:14, 마 5:44, 눅 23:34"},
        {"교리":"인내의 신학", "설명":"핍박에 참음 — ἀνέχομαι는 단순 참음이 아닌 하나님의 섭리를 신뢰하며 견디는 믿음의 인내", "관련구절":"롬 5:3-4, 약 1:3-4, 히 12:1"}
