        {"상황":"자존감이 낮아져 자신을 쓸모없는 존재로 느끼는 성도", "성경원리":"바울은 세상의 찌꺼기 같은 존재임을 고백하면서도 그리스도 안의 정체성을 잃지 않음", "실제적용":"세상의 평가가 아닌 그리스도 안의 정체성이 자존감의 근거임을 확인"}
