        {"상황":"성도에게 본이 되어야 한다는 부담감에 눌린 목회자", "성경원리":"본받으라고 권할 수 있는 것은 완벽함이 아닌 그리스도를 향한 방향성에 기반함", "실제적용":"완벽한 모범이 아닌 그리스도를 향해 가는 동반자로서의 자기 이해를 돕는다"}
