        {"구절":"빌 2:19-23", "연결점":"디모데를 보내는 바울의 신뢰와 애정 — 나와 같은 마음으로 너희 사정을 진실히 생각할 자", "구분":"신약"},
        {"구절":"행 16:1-3", "연결점":"바울이 디모데를 제자로 삼은 역사적 배경", "구분":"신약"},
        {"구절":"갈 1:8-9", "연결점":"복음의 일관성과 불변성 — 다른 복음을 전하면 저주를 받을지어다", "구분":"신약"}
