        {"상황":"권위자가 없을 때 방종하거나 교만해지는 경향이 있는 성도", "성경원리":"하나님은 항상 임재하시며, 권위자의 부재가 방종의 허가가 아님", "실제적용":"하나님 앞에서(coram Deo) 사는 삶의 원칙 — 사람의 눈이 없어도 하나님 앞에서 동일하게 행동"}
