        {"구절":"고전 8:1", "연결점":"지식은 교만하게 하며 — 지식으로 인한 교만의 패턴", "구분":"신약"},
        {"구절":"잠 16:18", "연결점":"교만은 패망의 선봉이요 — 교만의 결과에 대한 경고", "구분":"구약"},
        {"구절":"고후 10:10-11", "연결점":"편지로만 권위를 행사하는 것이 아닌 직접 임재로도 권위를 행사함", "구분":"신약"}
