        {"구분":"구약 예표", "내용":"모세가 바로에게 표적을 행함 — 말만이 아닌 능력으로 하나님의 권위를 증명(출 7-11장)", "그리스도연결":"하나님의 사역자의 권위는 능력으로 확인된다"}
